CREATE TABLE incidents(incident_id text NOT NULL,version text NOT NULL,service text NOT NULL,environment text NOT NULL,severity text,status text NOT NULL,payload jsonb NOT NULL,evidence_boundary text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(incident_id,version));
CREATE TABLE incident_signals(incident_id text NOT NULL,incident_version text NOT NULL,signal_id text NOT NULL,source text NOT NULL,status text NOT NULL,confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1),observed_at timestamptz NOT NULL,payload jsonb NOT NULL,synthetic boolean NOT NULL DEFAULT true,PRIMARY KEY(incident_id,incident_version,signal_id));
CREATE TABLE response_plans(plan_fingerprint text PRIMARY KEY,incident_id text NOT NULL,incident_version text NOT NULL,playbook_id text NOT NULL,playbook_version text NOT NULL,severity text NOT NULL,payload jsonb NOT NULL,auto_execute boolean NOT NULL DEFAULT false CHECK(auto_execute=false),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE action_approvals(approval_fingerprint text PRIMARY KEY,plan_fingerprint text NOT NULL REFERENCES response_plans(plan_fingerprint),action_id text NOT NULL,reviewer_id text NOT NULL,reviewer_role text NOT NULL,decision text NOT NULL,rationale text NOT NULL,execution_authorized boolean NOT NULL DEFAULT false CHECK(execution_authorized=false),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incident_timeline(event_hash text PRIMARY KEY,incident_id text NOT NULL,event_id text NOT NULL UNIQUE,previous_hash text NOT NULL,actor_id text NOT NULL,actor_role text NOT NULL,event_type text NOT NULL,occurred_at timestamptz NOT NULL,payload jsonb NOT NULL);
CREATE TABLE status_drafts(draft_fingerprint text PRIMARY KEY,incident_id text NOT NULL,payload jsonb NOT NULL,published boolean NOT NULL DEFAULT false CHECK(published=false),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE postmortems(postmortem_fingerprint text PRIMARY KEY,incident_id text NOT NULL,incident_version text NOT NULL,owner_id text NOT NULL,root_cause_status text NOT NULL,payload jsonb NOT NULL,auto_close boolean NOT NULL DEFAULT false CHECK(auto_close=false),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incident_dlq(job_id text PRIMARY KEY,attempts integer NOT NULL,reason text NOT NULL,auto_replay boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
